cd /Users/luke/Projects/personal/tokenjuice
node - <<'EOF'
const fs = require('fs');
const p = 'package.json';
let t = fs.readFileSync(p, 'utf8');
const before = t;

// 1. Append chmod to the build script (robust: independent of pre/post-script settings). Idempotent.
if (!t.includes('dist/rules/ && chmod +x dist/cli/main.js')) {
  t = t.replace(
    '&& cp -R src/rules/. dist/rules/",',
    '&& cp -R src/rules/. dist/rules/ && chmod +x dist/cli/main.js",'
  );
}

// 2. Collapse consecutive duplicate postbuild-chmod lines down to a single one (fixes duplicate-key cruft).
t = t.replace(
  /(^[ \t]*"postbuild": "chmod \+x dist\/cli\/main\.js",\n)(?:[ \t]*"postbuild": "chmod \+x dist\/cli\/main\.js",\n)+/m,
  '$1'
);

if (t !== before) fs.writeFileSync(p, t);

const obj = JSON.parse(fs.readFileSync(p, 'utf8')); // throws if invalid
console.log('changed       :', t !== before);
console.log('JSON parse    : OK');
console.log('build         :', obj.scripts.build);
console.log('postbuild     :', JSON.stringify(obj.scripts.postbuild));
console.log('postbuild #   :', (fs.readFileSync(p,'utf8').match(/"postbuild":/g)||[]).length);
console.log('build has chmod:', /chmod \+x dist\/cli\/main\.js/.test(obj.scripts.build));
EOF

